'use strict';

// MODULES //

var tape = require( 'tape' );
var Value = require( '@stdlib/plot/vega/value/ctor' );
var RuleEncodingSet = require( '@stdlib/plot/vega/mark/rule/encoding-set' );
var isRuleMarkEncodingSet = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof isRuleMarkEncodingSet, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns `true` if provided a rule mark encoding set instance', function test( t ) {
	var values;
	var bool;
	var i;

	values = [
		new RuleEncodingSet({
			'x': new Value({
				'field': 'x',
				'scale': 'xScale'
			})
		})
	];
	for ( i = 0; i < values.length; i++ ) {
		bool = isRuleMarkEncodingSet( values[ i ] );
		t.strictEqual( bool, true, 'returns expected value when provided '+values[ i ] );
	}
	t.end();
});

tape( 'the function returns `false` if not provided a rule mark encoding set instance', function test( t ) {
	var values;
	var bool;
	var i;

	values = [
		'',
		'beep',
		'boop',
		'foo',
		'bar',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		[],
		{},
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		bool = isRuleMarkEncodingSet( values[ i ] );
		t.strictEqual( bool, false, 'returns expected value when provided '+values[ i ] );
	}
	t.end();
});
